import {linkedRowIds,availablePeriods} from './planning-contract.mjs';
import {mountSponsorSlot,clearSponsorSlots} from '../monetization/slots.mjs';
async function startWorkspace(){
let intelligenceModule,planningModule,renderSequence=0;
const money=value=>formatMoney(value,dataset().currency||'EUR');
const incomeStatement=rows=>baseStatement(rows,dataset().currency);
const breakEven=(rows,price=0)=>baseBreakEven(rows,price,dataset().currency);
const cashPosition=(rows,opening=0)=>baseCash(rows,opening,dataset().currency);
const totals=rows=>cashPosition(rows);
const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
const escape = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  person:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',
  building:'M4 21V4h12v17M2 21h20M16 10h4v11M8 8h4M8 12h4M8 16h4',
  briefcase:'M8 6V3h8v3M3 6h18v14H3ZM3 11l9 4 9-4M10 13h4',
  home:'m3 10 9-7 9 7M5 9v12h14V9M10 21v-7h4v7',
  rows:'M4 4h16v16H4ZM8 8h8M8 12h8M8 16h5',
  target:'M21 12a9 9 0 1 1-9-9M17 12a5 5 0 1 1-5-5M12 12l9-9M17 3h4v4',
  spark:'m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6Z',
  book:'M12 5C9 2 5 3 2 4v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v15',
  arrow:'M20 12H4m6-6-6 6 6 6', sun:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M20 4l-2 2M6 18l-2 2',
  code:'m8 5-6 7 6 7m8-14 6 7-6 7M14 3l-4 18', wallet:'M3 6h17v15H3ZM3 6l14-3v3M16 12h6v4h-6Z',
  up:'M5 16 12 9l4 4 6-8M16 5h6v6', down:'M5 8l7 7 4-4 6 8M16 19h6v-6', info:'M12 11v6m0-10v1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.spark}"/></svg>`;
function hydrateIcons() { $$('[data-icon]').forEach(e => e.innerHTML = icon(e.dataset.icon)); }
const financialLabels={revenue:'Ventas / ingresos',cogs:'Coste de ventas',opex:'Gasto operativo',depreciation:'Depreciación / amortización',interest:'Intereses',tax:'Impuesto sobre resultados',other_income:'Otros ingresos',capital:'Capital / préstamo / activo',unclassified:'Sin clasificar'};
const businessModel={salesChange:0,fixedReduction:0,variableReduction:0};
const config = {
  personal:{name:'Mi espacio personal', icon:'person', hello:'¡Hola, Alex! ☀', title:'Todo empieza por ti.', subtitle:'Un vistazo a tu dinero. Un paso más hacia tus metas.', goal:'Mi fondo de tranquilidad', target:5000, saved:3600, categories:['Vivienda','Compra','Servicios','Suscripciones','Ocio','Transporte'], lesson:'Un colchón para vivir más tranquilo'},
  business:{name:'Estudio Norte', icon:'building', hello:'TU EMPRESA, CON PERSPECTIVA', title:'Más claridad. Más futuro.', subtitle:'Los números de tu negocio, conectados con tus próximos pasos.', goal:'Reserva operativa', target:80000, saved:48000, categories:['Equipo','Proveedores','Servicios','Suscripciones','Marketing','Operaciones'], lesson:'La caja y el beneficio no son lo mismo'},
  advisor:{name:'Mi cartera de clientes', icon:'briefcase', hello:'TU ESPACIO PROFESIONAL', title:'Números que puedes explicar.', subtitle:'Explora cada entidad y comparte un análisis con sus fuentes.', goal:'Reserva de la entidad', target:45000, saved:27000, categories:['Equipo','Proveedores','Servicios','Suscripciones','Marketing','Operaciones'], lesson:'Una buena conclusión empieza con evidencia'},
};
function seed(profile, entity = 0) {
  const c=config[profile], business=profile!=='personal', factor=profile==='advisor'?[.7,1.15,.48][entity]:1;
  const expenses=business?[17000,8500,2700,1200,5300,3700]:[1100,450,180,129,621,480];
  const income=business?52000:4200;
  const rows=[];
  for(let m=5;m<=10;m++) {
    const f = m===10?1:[.83,.9,.87,.95,.96][m-5];
    rows.push({id:`seed-${profile}-${entity}-${m}-income`,date:`2026-${String(m).padStart(2,'0')}-01`,description:business?'Ingresos por servicios':'Nómina y proyectos',category:business?'Ventas':'Trabajo',type:'ingreso',amount:Math.round(income*f*factor),source:'Datos de ejemplo'});
    expenses.forEach((amount,i)=>rows.push({id:`seed-${profile}-${entity}-${m}-${i}`,date:`2026-${String(m).padStart(2,'0')}-${String([2,5,10,15,20,24][i]).padStart(2,'0')}`,description:business?['Nóminas del equipo','Facturas de proveedores','Servicios del estudio','Herramientas digitales','Campaña del mes','Gastos de operaciones'][i]:['Alquiler de casa','Compra del mes','Luz, agua e internet','Suscripciones digitales','Restaurantes y ocio','Transporte y movilidad'][i],category:c.categories[i],type:'gasto',amount:Math.round(amount*(m===10?1:.85+ m*.012)*factor*100)/100,source:'Datos de ejemplo'}));
  }
  return {rows,goal:{name:c.goal,target:c.target,saved:c.saved},lessons:[],updated:'2026-10-27'};
}
const STORAGE=workspaceStorageKey(), dataScope=scopeFromStorageKey(STORAGE);
const workspaceStore=await openWorkspaceStorage({key:STORAGE,legacyStorage:localStorage,initialState:{month:'2026-10',profile:'personal',entity:0,datasets:{}}});
const saved=workspaceStore.read();
window.addEventListener('pagehide',()=>workspaceStore.close(),{once:true});
window.addEventListener('pageshow',event=>{if(event.persisted)location.reload();});
const state={...saved,profile:saved.profile||'personal',view:'overview',month:saved.month||'2026-10',entity:saved.entity||0,filter:'Todas',chart:'six',scenario:saved.scenario||{monthly:200,years:5,rate:3,fee:.5,inflation:2},theme:saved.theme||'light',previewCurrency:isCurrencyCode(saved.previewCurrency)?saved.previewCurrency:'EUR',datasets:saved.datasets||{}};
let toastTimer,transition,saving=false;
let lastCommitted=JSON.parse(JSON.stringify(savedState()));
function dataset(){
  const key=state.profile==='advisor'?`advisor-${state.entity}`:state.profile;let value=state.datasets[key];
  if(!value||!Array.isArray(value.rows)||!value.goal||!Array.isArray(value.lessons))value=state.datasets[key]=state.profile==='advisor'&&state.entity>=3?emptyClient(`Cliente ${state.entity+1}`,'EUR',state.month):seed(state.profile,state.entity);
  value.finance ||= {};value.budgets ||= {};if(!isCurrencyCode(value.currency))value.currency='EUR';
  for(const r of value.rows) if(!r.financialType&&r.source==='Datos de ejemplo'){
    r.financialType=r.type==='ingreso'?'revenue':r.category==='Proveedores'?'cogs':'opex';
    if(r.type==='gasto')r.behavior=['Proveedores','Marketing','Operaciones','Compra','Ocio','Transporte'].includes(r.category)?'variable':'fixed';
  }
  return value;
}
function monthSettings(){const d=dataset();return d.finance[state.month] ||= {opening:0,savingsTarget:20,expenseBudget:0,unitPrice:0};}
function previousRows(){const date=new Date(state.month+'-01T00:00:00Z');date.setUTCMonth(date.getUTCMonth()-1);const key=date.toISOString().slice(0,7);return dataset().rows.filter(r=>r.date.startsWith(key));}
function activeNavs(){return navs.filter(n=>n[0]!=='results'||state.profile!=='personal');}
function savedState(){const data={...state};for(const key of ['view','filter','chart','reviewCategory'])delete data[key];return {...data,period:state.month};}
function dataTools(){showDataTools({getState:savedState,scope:dataScope,modal,download,toast,
 readRecovery:()=>workspaceStore.readRecovery(),
 restore:async incoming=>{
  if(saving)throw new Error('Espera a que termine el guardado actual.');
  saving=true;saveStatus('Guardando…');
  try{await workspaceStore.save(savedState());await workspaceStore.save(incoming,{recovery:true});}
  finally{saving=false;}
  const restored=toWebState(incoming);for(const key of Object.keys(state))delete state[key];
  Object.assign(state,{filter:'Todas',chart:'six',scenario:{monthly:200,years:5,rate:3,fee:.5,inflation:2},...restored,view:'overview'});
  lastCommitted=JSON.parse(JSON.stringify(savedState()));document.documentElement.classList.toggle('dark',state.theme==='dark');refreshPreviewCurrency();route(state.profile,'overview');
 }});}
function saveStatus(text){const el=$('.local-indicator');if(el)el.replaceChildren(document.createElement('i'),document.createTextNode(text));}
function saveError(error){toast(error.message||'No se pudo guardar. Los datos anteriores se conservan.');const el=$('#form-error');if(el)el.textContent=error.message;}
async function persist(){
 if(saving)throw new Error('Espera a que termine el guardado actual.');
 saving=true;saveStatus('Guardando…');let success=false;
 try{
  const key=state.profile==='advisor'?`advisor-${state.entity}`:state.profile;if(state.datasets[key])state.datasets[key].lastMonth=state.month;
  await workspaceStore.save(savedState());lastCommitted=JSON.parse(JSON.stringify(savedState()));success=true;
 }catch(error){
  const transient={view:state.view,filter:state.filter,chart:state.chart};for(const key of Object.keys(state))delete state[key];
  Object.assign(state,JSON.parse(JSON.stringify(lastCommitted)),transient);
  document.documentElement.classList.toggle('dark',state.theme==='dark');refreshPreviewCurrency();throw error;
 }finally{saving=false;saveStatus(success?'Guardado en este dispositivo':'Guardado pendiente · revisa el aviso');}
}

function currentRows(){return dataset().rows.filter(r=>r.date.startsWith(state.month));}
function balance(){return cashPosition(currentRows(),monthSettings().opening||0);}
const monthName = value=>new Intl.DateTimeFormat('es-ES',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(value+'-01T00:00:00Z'));
const shortMonth = value=>new Intl.DateTimeFormat('es-ES',{month:'short',timeZone:'UTC'}).format(new Date(value+'-01T00:00:00Z')).replace('.','');
const animate=(targets,options)=>{if(window.gsap&&!matchMedia('(prefers-reduced-motion: reduce)').matches)return gsap.fromTo(targets,{autoAlpha:0,y:16},{autoAlpha:1,y:0,duration:.45,stagger:.045,ease:'power3.out',...options});};
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;if(window.gsap&&!matchMedia('(prefers-reduced-motion: reduce)').matches)gsap.to('#toast',{opacity:1,y:0,duration:.2});else{$('#toast').style.opacity=1;$('#toast').style.transform='translate(-50%,0)';}toastTimer=setTimeout(()=>{$('#toast').style.opacity=0;},3500);}
function modal(html){$('#dialog-content').innerHTML=html;hydrateIcons();if(!$('#detail-dialog').open)$('#detail-dialog').showModal();animate('#detail-dialog',{scale:1});}
function showProfiles(){$('#onboarding').showModal();animate('#onboarding');}
const navs=[['overview','Resumen','home'],['transactions','Movimientos','rows'],['planning','Planificar','target'],['results','Resultados','building'],['leaks','Fugas','down'],['goals','Objetivos','target'],['opportunities','Oportunidades','spark'],['learn','Aprender','book']];
function route(profile,view='overview'){const next=`#app/${profile}/${view}`;if(location.hash===next)renderRoute();else location.hash=next;}
function refreshPreviewCurrency(){const select=$('#preview-currency');if(!select)return;select.innerHTML=currencyOptions.map(c=>`<option value="${c.code}" ${c.code===state.previewCurrency?'selected':''}>${c.code}</option>`).join('');$$('[data-preview-money]').forEach(el=>el.textContent=formatMoney(Number(el.dataset.previewMoney),state.previewCurrency));$('#preview-goal-money').textContent=formatMoney(3600,state.previewCurrency)+' de '+formatMoney(5000,state.previewCurrency);}
function renderRoute(){
  const parts=location.hash.replace('#','').split('/');
  if(parts[0]!=='app'){transition?.kill();$('#workspace').hidden=true;$('#landing').hidden=false;$('.skip').href='#main';mountSponsorSlot('landing_footer');return;}
  if(!config[parts[1]])return route('personal');
  const changed=state.profile!==parts[1];state.profile=parts[1];state.view=activeNavs().some(n=>n[0]===parts[2])?parts[2]:'overview';
  if(changed){state.month=dataset().lastMonth||'2026-10';state.filter='Todas';}
  $('#landing').hidden=true;$('#workspace').hidden=false;$('.skip').href='#app-content';$('#onboarding').close();
  const c=config[state.profile];$('#profile-name').textContent=PROFILE_NAMES[state.profile];$('#workspace-name').textContent=c.name;$('#profile-avatar').innerHTML=icon(c.icon);
  $('#app-nav').innerHTML=activeNavs().map(([view,label,ico])=>`<button class="nav-button ${view===state.view?'active':''}" data-view="${view}" aria-label="${label}" ${view===state.view?'aria-current="page"':''}><span>${icon(ico)}</span><span>${label}</span>${view==='learn'?'<span class="new-tag">A tu ritmo</span>':''}</button>`).join('');
  $('#breadcrumb').textContent=`${PROFILE_NAMES[state.profile]} / ${navs.find(n=>n[0]===state.view)[1]} ⌄`;
  render();persist().catch(saveError);window.scrollTo({top:0,behavior:'instant'});
}
function header(title,desc,actions='',greeting='TU ESPACIO FINANCIERO') {return `<div class="page-heading"><div><div class="eyebrow">${greeting}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
function monthsSelect(){const months=availablePeriods(dataset(),state.month);return `<select id="month-select" aria-label="Periodo">${months.map(m=>`<option value="${m}" ${state.month===m?'selected':''}>${monthName(m)}</option>`).join('')}</select>`;}
function entitySelector(){return state.profile==='advisor'?`<div class="entity-list" aria-label="Entidades">${listClients(state).filter(c=>!c.archived).map(c=>`<button class="entity-button ${state.entity===c.index?'active':''}" data-entity="${c.index}">${icon('building')}${escape(c.name)}</button>`).join('')}<button class="entity-button" data-action="clients">${icon('briefcase')}Gestionar clientes</button></div>`:'';}
function clientTools(){
 const change=async transform=>{Object.assign(state,transform({...state,period:state.month}));state.month=dataset().lastMonth||state.month;await persist();render();};
 showClientTools({getState:()=>state,modal,create:options=>change(s=>createClient(s,options)),archive:index=>change(s=>setClientArchived(s,index,true)),restore:index=>change(s=>setClientArchived(s,index,false)),select:index=>change(s=>({...s,entity:index}))});
}
function results(){return header('Entiende qué deja tu negocio.','Resultados, punto de equilibrio y decisiones con los supuestos a la vista.',`${monthsSelect()}<button class="button small secondary" data-action="report">Exportar informe ↗</button>`)+entitySelector()+renderResults({rows:currentRows(),settings:monthSettings(),money,currency:dataset().currency,model:businessModel})+`<details class="advanced-analysis panel" id="advanced-analysis"><summary><span><span class="overline">UN POCO MÁS DE PERSPECTIVA</span><strong>Explorar el análisis avanzado</strong><small>Indicadores, proyecciones y decisiones que puedes explicar.</small></span><span class="advanced-arrow" aria-hidden="true">↗</span></summary><div id="financial-intelligence"><p class="scenario-note">Preparando tus indicadores…</p></div></details>`;}
function leaks(){return header('Encuentra por dónde se escapa.','Revisa gastos repetidos, variaciones, presupuestos y comisiones.',monthsSelect())+entitySelector()+renderLeaks({rows:currentRows(),previous:previousRows(),settings:monthSettings(),budgets:effectiveBudgets(dataset(),state.month),findings:workspaceLeaks(dataset(),state.month),money,currency:dataset().currency});}
function planning(){return header('Dale espacio a lo que viene.','Recurrentes, deudas, patrimonio y presupuestos, con tus datos y tus decisiones.',monthsSelect())+entitySelector()+'<div id="planning-panel"><p class="panel">Preparando tu planificación…</p></div>';}
function stats(){const b=balance(),s=monthSettings();return `<div class="stats">${[
 ['Disponible en caja',money(b.available),'wallet',`Saldo inicial ${money(b.opening)} + flujo ${money(b.net)}`,'blue','settings','Ajustar disponible'],
 ['Ingresos',money(b.income),'up',`${currentRows().filter(r=>r.type==='ingreso').length} movimientos de entrada`,'green','add-income','Añadir ingreso'],
 ['Gastos',money(b.expense),'down',`${currentRows().filter(r=>r.type==='gasto'&&r.financialType!=='depreciation').length} movimientos de salida`,'','add-expense','Añadir gasto'],
 [state.profile==='personal'?'Tasa de ahorro':'Margen de caja',b.rate===null?'N/D':`${b.rate.toFixed(1).replace('.',',')}%`,'target',`Meta ${s.savingsTarget}% · calculado sobre ingresos`,'green','settings','Editar meta de ahorro']
 ].map(([label,value,ico,note,color,action,link])=>`<article class="stat"><div class="stat-top">${label}${icon(ico)}</div><strong>${value}</strong><small class="${color}">${note}</small><button class="stat-action" data-action="${action}">${link} ↗</button></article>`).join('')}</div>`;}
function chart(){let months=[...new Set(dataset().rows.map(r=>r.date.slice(0,7)))].sort().filter(m=>m<=state.month).slice(state.chart==='three'?-3:-6);const data=months.map(m=>totals(dataset().rows.filter(r=>r.date.startsWith(m))));const max=Math.max(1,...data.flatMap(d=>[d.income,d.expense]));return `<section class="panel"><div class="panel-title"><h2>Tu dinero, en perspectiva</h2><div class="segment"><button data-chart="three" class="${state.chart==='three'?'selected':''}">3 meses</button><button data-chart="six" class="${state.chart==='six'?'selected':''}">6 meses</button></div></div><div class="chart-summary"><span><i></i> Ingresos</span><span><i></i> Gastos</span></div><div class="bar-chart" role="img" aria-label="Ingresos y gastos por mes: ${escape(months.map((m,i)=>`${shortMonth(m)} ingresos ${money(data[i].income)}, gastos ${money(data[i].expense)}`).join('; '))}">${data.map((d,i)=>`<div class="chart-pair" title="${escape(`${monthName(months[i])}: ingresos ${money(d.income)}, gastos ${money(d.expense)}`)}"><i style="height:${d.income/max*92}%"></i><i style="height:${d.expense/max*92}%"></i></div>`).join('')}</div><div class="bar-labels">${months.map(m=>`<span>${shortMonth(m)}</span>`).join('')}</div><button class="evidence-button" data-evidence="cash">${icon('info')} Cómo se calcula · Ver los datos</button></section>`;}
function goalPanel(){const g=dataset().goal,pct=Math.min(100,Math.round(g.saved/g.target*100));return `<section class="panel"><div class="panel-title"><h2>Un objetivo, más cerca</h2><span class="status-label">EN CAMINO</span></div><div class="goal-row"><span class="goal-icon">${icon('target')}</span><div><h3>${escape(g.name)}</h3><p>Una meta que te da tranquilidad.</p></div></div><div class="goal-amount"><b>${money(g.saved)}</b><span>de ${money(g.target)}</span></div><div class="progress-track" role="progressbar" aria-label="Progreso del objetivo" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><i style="width:${pct}%"></i></div><div class="goal-tip">✦ ${pct}% completado. Cada pequeño paso cuenta.</div><button class="outline-action" data-action="goal">Actualizar mi progreso →</button></section>`;}
function recent(){const rows=[...currentRows()].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);return `<section class="panel"><div class="panel-title"><h2>Los últimos movimientos</h2><button class="text-button" data-view="transactions">Ver todos ↗</button></div><ul class="transaction-list">${rows.map(r=>`<li class="transaction-row"><span class="transaction-icon ${r.type==='ingreso'?'income':''}">${icon(r.type==='ingreso'?'up':'wallet')}</span><div><b>${escape(r.description)}</b><small>${escape(r.category)} · ${r.date.slice(8)}/${r.date.slice(5,7)}</small></div><strong class="${r.type==='ingreso'?'income':''}">${r.type==='ingreso'?'+':'−'}${money(r.amount)}</strong></li>`).join('')||'<li class="empty">Todavía no hay movimientos. Añade el primero.</li>'}</ul></section>`;}
function overview(){
  const c=config[state.profile],select=monthsSelect(),demo=dataset().rows.some(r=>r.source==='Datos de ejemplo');
  return header(c.title,c.subtitle,select,state.profile==='personal'?(getAccount()?`Hola, ${escape(getAccount().name)} ☀`:'TU ESPACIO PERSONAL'):c.hello)+entitySelector()+
  `<div class="quick-actions"><button class="button primary small" data-action="add-income">+ Añadir ingreso</button><button class="button secondary small" data-action="add-expense">+ Añadir gasto</button><button class="button secondary small" data-action="settings">Configurar mes</button><button class="text-button" data-action="import">Importar CSV ↗</button>${dataset().demoArchive?'<button class="text-button" data-action="restore-demo">Restaurar ejemplos</button>':''}</div>`+
  (demo?`<section class="welcome-banner"><div><span class="banner-spark">✧</span><div><h2>Este espacio incluye datos de ejemplo.</h2><p>Empieza con tus datos o edita los registros para ver cómo cambia tu resumen.</p></div></div><button class="button" data-action="own-data">Usar mis datos →</button></section>`:'')+
  stats()+`<div class="dashboard-grid">${chart()}${goalPanel()}</div>`+
  (state.profile!=='personal'?`<div class="analysis-teaser panel"><div><h2>¿Cuánto necesitas vender para cubrir tus costes?</h2><p>Abre tu estado de resultados, clasifica los costes y explora el punto de equilibrio.</p></div><button class="button secondary small" data-view="results">Analizar resultados ↗</button></div>`:'')+
  `<div class="lower-grid">${recent()}<section class="panel learning-card"><div class="panel-title"><h2>¿Por dónde se va tu dinero?</h2><small>REVISIÓN DEL MES</small></div><div class="learning-visual"><span class="coin">${dataset().currency}</span><span class="coin">✦</span><span class="coin">${dataset().currency}</span></div><h3>Encuentra señales que merecen atención.</h3><p>Cargos repetidos, aumentos por categoría, comisiones y presupuestos superados.</p><button class="button" data-view="leaks">Revisar posibles fugas →</button></section></div>`;
}
function transactions(){const select=monthsSelect();return header('Cada movimiento cuenta.','Añade, importa y entiende los números de tu mes.',`<button class="button primary small" data-action="add">+ Añadir</button>`)+entitySelector()+`<div class="filters"><input id="search" type="search" aria-label="Buscar movimientos" placeholder="Buscar un movimiento…"><select id="type-filter" aria-label="Tipo de movimiento"><option value="all">Todos los tipos</option><option value="ingreso">Ingresos</option><option value="gasto">Gastos</option></select>${select}<button class="button small secondary" data-action="import">Importar CSV</button><button class="button small secondary" data-action="export">Exportar CSV ↗</button>${dataset().trash?.length?'<button class="button small secondary" data-action="restore-row">Restaurar último archivado</button>':''}</div><section class="panel"><div class="panel-title"><h2>Movimientos de ${monthName(state.month)}</h2><small id="row-count"></small></div><div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Descripción</th><th>Categoría</th><th>Importe</th><th>Fuente</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody id="transaction-table"></tbody></table></div><div id="table-empty" class="empty" hidden>No encontramos movimientos con ese filtro.</div></section>`;}
function updateTable(){
 const search=($('#search')?.value||'').toLowerCase(),type=$('#type-filter')?.value||'all';
 const rows=[...currentRows()].filter(r=>(type==='all'||r.type===type)&&`${r.description} ${r.category}`.toLowerCase().includes(search)).sort((a,b)=>b.date.localeCompare(a.date));
 $('#transaction-table').innerHTML=rows.map(r=>`<tr><td>${r.date.slice(8)}/${r.date.slice(5,7)}</td><td class="description">${escape(r.description)}<small class="row-detail">${escape(financialLabels[r.financialType]||'Sin clasificar')} · ${r.behavior==='fixed'?'Fijo':r.behavior==='variable'?'Variable':'Por clasificar'}</small></td><td>${escape(r.category)}</td><td class="${r.type==='ingreso'?'amount-income':''}">${r.type==='ingreso'?'+':'−'}${money(r.amount)}</td><td>${escape(r.source||'Manual')}<small class="row-detail">ID: ${escape(r.id)}</small></td><td><button class="edit-button" data-edit="${escape(r.id)}" aria-label="Editar ${escape(r.description)}">Editar</button><button class="delete-button" data-delete="${escape(r.id)}" aria-label="Archivar ${escape(r.description)}">×</button></td></tr>`).join('');
 $('#row-count').textContent=`${rows.length} movimientos`;$('#table-empty').hidden=rows.length>0;
}
function goals(){
 const s=state.scenario;
 return header('Un futuro que se construye.','Tus objetivos, un paso a la vez. Explora lo que puede cambiar con constancia.')+entitySelector()+`<div class="dashboard-grid">${goalPanel()}<section class="panel"><div class="panel-title"><h2>Tu siguiente paso</h2></div><p class="scenario-note">Actualiza el dinero reservado para tu objetivo. Este registro es independiente de los movimientos: no realiza una transferencia ni modifica tu saldo.</p><button class="evidence-button" data-evidence="goal">${icon('info')} Ver la fórmula del objetivo</button></section></div><section class="panel scenario-panel"><div class="panel-title"><h2>¿Y si empiezas hoy?</h2><span class="demo-chip">SIMULACIÓN</span></div><div class="simulation"><div><p class="scenario-note">Cambia tus aportaciones, plazo y costes para entender su efecto.</p><label class="range-label" for="monthly">Aportación mensual <b id="monthly-value"></b></label><input id="monthly" type="range" min="0" max="2000" step="25" value="${s.monthly}"><label class="range-label" for="years">Tiempo <b id="years-value"></b></label><input id="years" type="range" min="1" max="30" value="${s.years}"><label class="range-label" for="rate">Rentabilidad anual hipotética <b id="rate-value"></b></label><input id="rate" type="range" min="-10" max="10" step=".5" value="${s.rate}"><label class="range-label" for="fee">Coste anual total hipotético <b id="fee-value"></b></label><input id="fee" type="range" min="0" max="5" step=".1" value="${s.fee}"><label class="range-label" for="inflation">Inflación anual hipotética <b id="inflation-value"></b></label><input id="inflation" type="range" min="0" max="10" step=".5" value="${s.inflation}"></div><div class="simulation-result"><small>Capital nominal, después del coste supuesto</small><strong id="scenario-balance"></strong><p id="scenario-detail"></p><p id="scenario-fee"></p><p id="scenario-real"></p><p>Tasas constantes e hipotéticas. Sin impuestos. No hay selección ni ejecución de inversiones.</p></div></div><button class="evidence-button" data-evidence="scenario">${icon('info')} Ver método y supuestos</button></section>`;
}
function updateScenario(){
 const s=state.scenario,netRate=((1+s.rate/100)*(1-s.fee/100)-1)*100;
 const gross=scenario(s.monthly,s.years*12,s.rate),result=scenario(s.monthly,s.years*12,netRate),real=result.balance/Math.pow(1+s.inflation/100,s.years);
 $('#monthly-value').textContent=money(s.monthly);$('#years-value').textContent=`${s.years} años`;$('#rate-value').textContent=`${s.rate}%`;$('#fee-value').textContent=`${s.fee}%`;$('#inflation-value').textContent=`${s.inflation}%`;
 $('#scenario-balance').textContent=money(result.balance);$('#scenario-detail').textContent=`${money(result.contributions)} aportados + ${money(result.growth)} de variación hipotética neta.`;
 $('#scenario-fee').textContent=`Diferencia acumulada frente al mismo escenario sin coste: ${money(gross.balance-result.balance)}.`;$('#scenario-real').textContent=`Poder adquisitivo estimado en dinero de hoy: ${money(real)}.`;
}
function opportunityData(){const b=balance(),subs=currentRows().filter(r=>r.type==='gasto'&&r.category.toLowerCase()==='suscripciones').reduce((s,r)=>s+r.amount,0),gap=Math.max(0,dataset().goal.target-dataset().goal.saved);return [
 {id:'subscriptions',kind:'Ahorro',ico:'wallet',tag:'HIPÓTESIS EDITORIAL',title:'Dale una vuelta a tus suscripciones.',desc:'¿Usas todo lo que pagas? Explora qué pasaría al reducir un 20% esta categoría.',impact:money(subs*.2*12),label:'Ahorro anual hipotético · reducción del 20%',value:subs,formula:`${money(subs)} × 20% × 12 meses`,limits:'El 20% es un supuesto de exploración, no una predicción. Revisa contratos, uso y costes de cancelación.'},
 {id:'reserve',kind:'Planificación',ico:'target',tag:'BASADO EN TU OBJETIVO',title:'Un poco más de tranquilidad.',desc:'Calcula cuánto queda para tu reserva y qué pasaría si mantuvieras tu flujo positivo.',impact:money(gap),label:'Importe pendiente para tu objetivo',value:gap,formula:`${money(dataset().goal.target)} − ${money(dataset().goal.saved)}`,limits:b.net>0?`Con un flujo neto constante de ${money(b.net)} al mes, cubrirías la diferencia en ${Math.ceil(gap/b.net)} meses. Asignar todo ese flujo puede no ser adecuado.`:'No hay flujo positivo este mes. Este cálculo no estima una fecha para alcanzar el objetivo.'},
 {id:'invest',kind:'Aprendizaje',ico:'book',tag:'EXPLORACIÓN EDUCATIVA',title:'Entiende antes de invertir.',desc:'Tiempo, riesgo y diversificación: descubre cómo cambian un escenario de inversión.',impact:'A tu ritmo',label:'Simulador de aportaciones · sin operaciones',value:0,formula:'Capital final = capital anterior × (1 + tasa mensual) + aportación',limits:'Una rentabilidad hipotética no es un pronóstico. No hay cotizaciones ni selección de valores en esta demo.'}
 ];}
function opportunities(){const items=opportunityData().filter(o=>state.filter==='Todas'||o.kind===state.filter);return header('Posibilidades con contexto.','Ideas para revisar, con sus fuentes, supuestos y límites a la vista.')+entitySelector()+`<div class="chips">${['Todas','Ahorro','Planificación','Aprendizaje'].map(f=>`<button class="chip ${f===state.filter?'selected':''}" data-filter="${f}">${f}</button>`).join('')}</div><div class="opportunity-grid">${items.map(o=>`<article class="panel opportunity"><span class="profile-icon">${icon(o.ico)}</span><div><span class="status-label">${o.tag}</span></div><h2>${o.title}</h2><p>${o.desc}</p><strong class="impact">${o.impact}</strong><small class="impact-label">${o.label}</small><button class="button secondary" data-opportunity="${o.id}">Entender esta oportunidad ↗</button></article>`).join('')}</div><p class="scenario-note">Estas ideas se calculan sobre el periodo seleccionado: ${monthName(state.month)}. Cambia el periodo desde Resumen o Movimientos.</p>`;}
const lessons=[
 {title:'Un colchón para tu tranquilidad',desc:'Empieza por entender tu fondo de reserva.',body:'Una reserva es dinero destinado a imprevistos. El importe que necesitas depende de tus gastos esenciales, la estabilidad de tus ingresos y tus responsabilidades. Mantenerlo accesible evita depender de vender inversiones en un mal momento.',question:'¿Qué caracteriza a una reserva para imprevistos?',answers:['Debe estar accesible cuando la necesitas.','Siempre debe invertirse en activos de alto riesgo.'],correct:0,explain:'La disponibilidad es clave. El objetivo de esta reserva es cubrir imprevistos, no maximizar la rentabilidad.'},
 {title:'La caja y el beneficio',desc:'Dos conceptos que cuentan historias distintas.',body:'Registrar una venta no siempre significa haber cobrado. El beneficio puede incluir ingresos pendientes; la caja refleja entradas y salidas efectivas. El registro simple de esta demo calcula flujo neto de movimientos, no un estado de resultados contable.',question:'Una factura pendiente de cobro…',answers:['Ya es dinero disponible en el banco.','Puede ser ingreso contable sin ser todavía caja.'],correct:1,explain:'El momento del cobro importa. Un negocio rentable también puede tener tensiones de liquidez.'},
 {title:'Pequeñas comisiones, efecto acumulado',desc:'Haz visibles los costes recurrentes.',body:'Los costes recurrentes reducen el dinero disponible. Antes de cambiar un servicio, compara coste total, uso y valor. Un ahorro hipotético solo se convierte en ahorro real cuando cambia un gasto efectivo.',question:'Antes de cancelar una suscripción conviene…',answers:['Revisar su uso, valor y condiciones.','Cancelar siempre la más cara sin revisar nada.'],correct:0,explain:'El precio no cuenta toda la historia: el valor recibido y las condiciones también importan.'},
 {title:'Tiempo, rendimiento y riesgo',desc:'Explora supuestos sin confundirlos con certezas.',body:'Una simulación usa supuestos para explorar posibilidades. Los rendimientos reales pueden variar, ser negativos y verse reducidos por inflación, impuestos y comisiones. Un escenario constante ayuda a entender la mecánica, pero no predice el futuro.',question:'Un simulador con un 3% constante…',answers:['Garantiza que ganarás un 3% cada año.','Describe un supuesto que puede no cumplirse.'],correct:1,explain:'La simulación es una herramienta de exploración. Un supuesto no es una garantía.'},
 {title:'Una decisión que puedes explicar',desc:'Busca fuente, fecha, fórmula y límites.',body:'Un resultado útil permite revisar sus datos de entrada, periodo, método y limitaciones. Si falta información, es mejor mostrar un dato no disponible que inventar una cifra. Esa es la base de la evidencia en FinFlow.',question:'¿Qué hace más verificable una conclusión?',answers:['Mostrar sus fuentes y la fórmula utilizada.','Ocultar los datos y mostrar solo una puntuación.'],correct:0,explain:'La trazabilidad te permite comprobar, corregir y entender el resultado.'}
];
function learn(){const completed=dataset().lessons;return header('Pequeñas lecciones. Grandes pasos.','Aprende a tu ritmo. Cada concepto te ayuda a decidir con más claridad.')+`<div class="lesson-layout"><div class="lesson-list">${lessons.map((l,i)=>`<button class="lesson-node ${completed.includes(i)?'complete':''}" data-lesson="${i}"><span class="lesson-circle">${completed.includes(i)?'✓':i+1}</span><span><b>${l.title}</b><small>${l.desc}</small></span><span>${completed.includes(i)?'Repasar ↗':'3 min →'}</span></button>`).join('')}</div><section class="panel learning-summary"><span class="big-star">✦</span><h2>La constancia suma.</h2><p>Sin prisas, sin comparaciones.<br>Lo que aprendes hoy te acompaña mañana.</p><div class="summary-count">${completed.length}<span style="font-size:17px;color:var(--muted)"> / ${lessons.length}</span></div><p>lecciones completadas</p><div class="progress-track"><i style="width:${completed.length/lessons.length*100}%"></i></div><p>Celebramos lo que aprendes, sin premiar operaciones ni asumir riesgos.</p></section></div>`;}
function render(){
 clearSponsorSlots();
 renderSequence++;intelligenceModule?.clearIntelligence();planningModule?.clearPlanning();
 transition?.kill();const views={overview,transactions,goals,opportunities,learn,results,leaks,planning};$('#app-content').innerHTML=views[state.view]();hydrateIcons();
 if(state.view==='transactions'){if(state.reviewCategory!==undefined){$('#search').value=state.reviewCategory;delete state.reviewCategory;}updateTable();}
 if(state.view==='goals')updateScenario();
 if(state.view==='planning')refreshPlanning();
 if(state.view==='learn'){$('#app-content').insertAdjacentHTML('beforeend','<aside class="sponsor-slot" data-sponsor-placement="learning_resources" aria-label="Patrocinios opcionales" hidden></aside>');mountSponsorSlot('learning_resources');}
 if(state.view==='results')$('#advanced-analysis').addEventListener('toggle',event=>{if(event.target.open)refreshIntelligence();});
 const sources=[...new Set(dataset().rows.map(r=>r.source))];$('#data-label').textContent=`${sources.includes('Datos de ejemplo')?'Incluye datos de ejemplo':'Datos propios'} · ${dataset().currency}`;$('#workspace-name').textContent=dataset().name||config[state.profile].name;$('#currency-toggle').textContent=dataset().currency+' ⌄';$('#currency-toggle').setAttribute('aria-label','Moneda del espacio: '+dataset().currency+'. Cambiar moneda');dataset().lastMonth=state.month;
 transition=animate('#app-content > *');$('#app-content').focus({preventScroll:true});
}
async function refreshPlanning(sequence=renderSequence){
 try{planningModule ||= await import('../components/workspace/PlanningPanel.jsx');if(sequence!==renderSequence||state.view!=='planning')return;planningModule.mountPlanning({dataset:dataset(),period:state.month,profile:state.profile,money,workspaceState:savedState(),onSelectClient:async index=>{try{const client=listClients(state).find(c=>c.index===index);if(!client||client.archived)return;const key=client.key;state.datasets[key] ||= emptyClient(client.name,client.currency,state.month);state.entity=index;await persist();route('advisor','overview');}catch(error){saveError(error);}},onSave:async change=>{const key=state.profile==='advisor'?`advisor-${state.entity}`:state.profile;state.datasets[key]=change(dataset());await persist();await refreshPlanning();}});}
 catch(error){const el=$('#planning-panel');if(el&&sequence===renderSequence)el.textContent=error.message||'No se pudo abrir la planificación. Tus datos guardados se conservan.';}
}
async function refreshIntelligence(sequence=renderSequence){
 try{intelligenceModule ||= await import('../components/workspace/FinancialIntelligence.jsx');if(sequence!==renderSequence||state.view!=='results'||!$('#advanced-analysis')?.open)return;intelligenceModule.mountIntelligence({dataset:{...dataset()},month:state.month,money,onSave:async analysis=>{dataset().analysis=analysis;await persist();refreshIntelligence();toast('Análisis guardado en esta entidad.');}});animate('#financial-intelligence',{duration:.3});}
 catch{const element=$('#financial-intelligence');if(element&&sequence===renderSequence)element.innerHTML='<p class="panel" role="alert">No se pudo cargar el análisis. Recarga la página para intentarlo de nuevo. Tus movimientos siguen guardados.</p>';}
}
function evidence(kind){
 const b=balance(),g=dataset().goal,s=state.scenario,netRate=((1+s.rate/100)*(1-s.fee/100)-1)*100;
 const items={cash:{title:'Los números, a la vista.',value:money(b.available),formula:`Disponible = saldo inicial ${money(b.opening)} + ingresos ${money(b.income)} − gastos de caja ${money(b.expense)}`,input:`${currentRows().length} movimientos. Periodo ${monthName(state.month)}.`,limits:'Los movimientos de depreciación no salen de caja. La tasa es flujo neto / ingresos; es N/D si no hay ingresos. No se verifica el saldo contra un banco.'},goal:{title:'Tu objetivo, paso a paso.',value:`${Math.min(100,Math.round(g.saved/g.target*100))}%`,formula:`Progreso = ${money(g.saved)} reservados ÷ ${money(g.target)} objetivo × 100`,input:'Importes declarados en el formulario del objetivo.',limits:'El importe reservado es un registro separado. No se comprueba contra una cuenta bancaria ni genera transferencias.'},scenario:{title:'Un escenario, explicado.',value:money(scenario(s.monthly,s.years*12,netRate).balance),formula:'Tasa neta anual = (1 + tasa bruta) × (1 − coste anual) − 1. Cada mes: saldo = saldo × (1 + tasa neta anual / 12) + aportación al final del mes. Valor real = nominal / (1 + inflación)^años.',input:`${money(s.monthly)} al mes, ${s.years} años, tasa bruta ${s.rate}%, coste ${s.fee}%, inflación ${s.inflation}%. Saldo inicial cero.`,limits:'Tasas constantes e hipotéticas, sin impuestos. El coste modelado reduce la tasa; no replica una tarifa real concreta ni es un pronóstico.'}};
 const o=items[kind];modal(`<span class="overline">EVIDENCIA · ${kind}.v2</span><h2>${o.title}</h2><div class="evidence-value">${o.value}</div><dl class="evidence-details"><dt>Fórmula</dt><dd>${o.formula}</dd><dt>Entradas</dt><dd>${o.input}</dd><dt>Fuente</dt><dd>${kind==='scenario'?'Supuestos del simulador':escape([...new Set(currentRows().map(r=>r.source||'Manual'))].join(' · '))||'Sin movimientos'} · almacenamiento local</dd><dt>Calculado</dt><dd>${new Intl.DateTimeFormat('es-ES',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Toronto'}).format(new Date())} · America/Toronto</dd><dt>Límites</dt><dd>${o.limits}</dd></dl>`);
}
function financialOptions(type,selected){return (type==='ingreso'?['revenue','other_income','capital']:['opex','cogs','interest','tax','depreciation','capital','unclassified']).map(k=>`<option value="${k}" ${k===selected?'selected':''}>${financialLabels[k]}</option>`).join('');}
function addTransaction(type='gasto',existing=null){
  const r=existing||{type,description:'',date:state.month+'-27',category:'Otros',amount:'',financialType:type==='ingreso'?'revenue':'opex',behavior:''};
  modal(`<span class="overline">${existing?'ACTUALIZAR REGISTRO':'UN MOVIMIENTO MÁS CLARO'}</span><h2>${existing?'Edita tu movimiento.':r.type==='ingreso'?'Añade un ingreso.':'Añade un gasto.'}</h2><form id="transaction-form"><input type="hidden" name="transactionId" value="${escape(r.id||'')}"><label class="field">Descripción<input name="description" required maxlength="200" value="${escape(r.description)}" placeholder="Por ejemplo, compra del mes"></label><div class="form-grid"><label class="field">Importe (${dataset().currency})<input name="amount" type="number" min="${currencyStep(dataset().currency)}" max="1000000000000" step="${currencyStep(dataset().currency)}" required value="${r.amount}"></label><label class="field">Tipo<select name="type" id="transaction-type"><option value="gasto" ${r.type==='gasto'?'selected':''}>Gasto</option><option value="ingreso" ${r.type==='ingreso'?'selected':''}>Ingreso</option></select></label><label class="field">Fecha<input name="date" type="date" required value="${r.date}"></label><label class="field">Categoría<input name="category" required maxlength="80" value="${escape(r.category)}" list="category-options"><datalist id="category-options">${[...new Set([...config[state.profile].categories,'Comisiones','Ventas','Trabajo','Otros'])].map(c=>`<option value="${c}">`).join('')}</datalist></label></div><label class="field">Clasificación para resultados<select name="financialType" id="financial-type">${financialOptions(r.type,r.financialType)}</select></label><label class="field">Comportamiento del coste<select name="behavior"><option value="">Pendiente / no aplica</option><option value="fixed" ${r.behavior==='fixed'?'selected':''}>Fijo</option><option value="variable" ${r.behavior==='variable'?'selected':''}>Variable</option></select></label><p class="scenario-note">Clasifica los costes operativos como fijos o variables para calcular el punto de equilibrio. La depreciación afecta resultados, pero no el disponible en caja.</p><p class="field-error" id="form-error" role="alert"></p><button class="button primary" type="submit">${existing?'Guardar cambios':'Guardar movimiento'} →</button></form>`);
}
function currencyOptionsHTML(selected,entries=currencyOptions){return entries.map(c=>`<option value="${c.code}" ${c.code===selected?'selected':''}>${escape(c.code+' · '+c.name)}</option>`).join('');}
function showCurrencies(){modal(`<span class="overline">LA MONEDA DE TU ESPACIO</span><h2>Elige tu moneda.</h2><form id="currency-form"><label class="field">Buscar por nombre o código<input id="currency-search" type="search" placeholder="CLP, peso argentino, dólar…" autocomplete="off" maxlength="80"></label><label class="field">Moneda<select id="currency-choice" name="currency" size="8" required>${currencyOptionsHTML(dataset().currency)}</select></label><small id="currency-count" role="status">${currencyOptions.length} monedas</small><p class="scenario-note">Se aplica a este espacio o cliente. Los importes se conservan: esta selección no realiza una conversión de divisas.</p><button class="button primary" id="currency-save" type="submit">Guardar moneda →</button></form>`);$('#currency-search').focus();}
function configureMonth(){
 const s=monthSettings(),d=dataset();
 modal(`<span class="overline">TUS DATOS, TU MES</span><h2>Configura tu espacio.</h2><form id="settings-form"><label class="field">Nombre del espacio o cliente<input name="name" required maxlength="80" value="${escape(d.name||config[state.profile].name)}"></label><div class="form-grid"><label class="field">Mes de trabajo<input type="month" name="month" required value="${state.month}"></label><label class="field">Moneda<select name="currency">${currencyOptions.map(c=>`<option value="${c.code}" ${d.currency===c.code?'selected':''}>${escape(c.code+' · '+c.name)}</option>`).join('')}</select></label></div><label class="field">Disponible actual (${d.currency})<input type="number" name="available" step="${currencyStep(dataset().currency)}" min="-1000000000000" max="1000000000000" required value="${balance().available}"></label><p class="scenario-note">Se ajustará el saldo inicial del mes: disponible indicado − flujo neto registrado. Tus ingresos y gastos se conservan.</p><div class="form-grid"><label class="field">Meta de ahorro (%)<input type="number" name="savingsTarget" min="0" max="100" step=".1" required value="${s.savingsTarget}"></label><label class="field">Presupuesto de gastos mensual<input type="number" name="expenseBudget" min="0" max="1000000000000" step="${currencyStep(dataset().currency)}" required value="${s.expenseBudget||0}"></label></div>${state.profile!=='personal'?`<label class="field">Precio medio de venta por unidad (opcional)<input type="number" name="unitPrice" min="0" max="1000000000000" step="${currencyStep(dataset().currency)}" value="${s.unitPrice||0}"></label>`:''}<p class="scenario-note">La tasa real se calcula desde los movimientos; la meta es el objetivo que eliges. Presupuesto 0 significa sin límite. Cambiar moneda no convierte los importes existentes.</p><p class="field-error" id="form-error" role="alert"></p><button class="button primary" type="submit">Guardar configuración →</button></form>`);
}
function budgetForm(category=''){
 modal(`<span class="overline">UN LÍMITE CON INTENCIÓN</span><h2>Planifica una categoría.</h2><form id="budget-form"><label class="field">Categoría<input name="category" required maxlength="80" value="${escape(category)}" placeholder="Ej. Suscripciones"></label><label class="field">Presupuesto mensual (${dataset().currency})<input name="limit" type="number" min="0" max="1000000000000" step="${currencyStep(dataset().currency)}" required value="${effectiveBudgets(dataset(),state.month)[category] ?? 0}"></label><label class="field">Período<input type="month" name="period" required value="${state.month}"></label><p>Se aplica solo al mes elegido. Cero representa cero gasto previsto. Los límites anteriores se conservan como valores heredados.</p><button class="button primary" type="submit">Guardar presupuesto →</button></form>`);
}
function editGoal(){const g=dataset().goal,c=dataset().currency;modal(`<span class="overline">UN PASO HACIA TU META</span><h2>Dale forma a tu objetivo.</h2><form id="goal-form"><label class="field">Nombre de tu objetivo<input name="name" required maxlength="80" value="${escape(g.name)}"></label><label class="field">Importe objetivo (${c})<input type="number" name="target" min="1" max="1000000000000" required step="${currencyStep(dataset().currency)}" value="${g.target}"></label><label class="field">Dinero reservado (${c})<input type="number" name="saved" min="0" max="1000000000000" required step="${currencyStep(dataset().currency)}" value="${g.saved}"></label><p>Este registro no mueve dinero. Actualiza cuánto tienes reservado realmente.</p><p class="field-error" id="form-error" role="alert"></p><button class="button primary" type="submit">Guardar mi progreso →</button></form>`);}
function openLesson(index){const l=lessons[index];modal(`<span class="overline">LECCIÓN ${index+1} DE ${lessons.length} · 3 MIN</span><h2>${l.title}</h2><p>${l.body}</p><h3 style="font-size:14px;margin-top:25px">${l.question}</h3>${l.answers.map((a,i)=>`<button class="quiz-option" data-answer="${i}" data-quiz="${index}">${a}</button>`).join('')}<p id="quiz-feedback" role="status"></p><button class="button primary" id="lesson-done" hidden>Continuar mi camino →</button>`);}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',event=>{if(saving){event.preventDefault();event.stopImmediatePropagation();toast('Espera a que termine el guardado actual.');}},true);
$('#detail-dialog').addEventListener('cancel',event=>{if(saving)event.preventDefault();});
document.addEventListener('click',async event=>{try{
  const b=event.target.closest('button,a');if(!b)return;
  if(b.dataset.profile){route(b.dataset.profile);return;}
  if(b.hasAttribute('data-start'))return showProfiles();
  if(b.dataset.edit){const r=dataset().rows.find(r=>r.id===b.dataset.edit);if(r)addTransaction(r.type,r);return;}
  if(b.dataset.action==='add-income')return addTransaction('ingreso');
  if(b.dataset.action==='add-expense')return addTransaction('gasto');
  if(b.dataset.action==='currency')return showCurrencies();
  if(b.dataset.action==='settings')return configureMonth();
  if(b.dataset.action==='budget')return budgetForm();
  if(b.hasAttribute('data-budget-category'))return budgetForm(b.dataset.budgetCategory);
  if(b.hasAttribute('data-review-category')){state.reviewCategory=b.dataset.reviewCategory==='Todas'?'':b.dataset.reviewCategory;route(state.profile,'transactions');return;}
  if(b.dataset.action==='report'){
    const p=incomeStatement(currentRows()),bep=breakEven(currentRows(),monthSettings().unitPrice);
    download(`finflow-resultados-${state.month}.json`,JSON.stringify({space:dataset().name||config[state.profile].name,profile:state.profile,period:state.month,currency:dataset().currency,basis:'Gestión, base caja y clasificación declarada; depreciación separada',statement:p,breakEven:bep,rows:currentRows(),calculatedAt:new Date().toISOString()},null,2),'application/json');toast('Informe exportado con sus registros y cálculos.');return;
  }
  if(b.dataset.action==='own-data'){modal('<span class="overline">TU PROPIO PUNTO DE PARTIDA</span><h2>Empieza con tus números.</h2><p>Retiraremos solo los movimientos de ejemplo de este espacio. Tus movimientos manuales e importados se conservarán. El importe reservado del objetivo se pondrá a cero para que lo actualices con tus datos.</p><p>Se guardará una copia local de los ejemplos para poder restaurarlos.</p><button class="button primary" id="confirm-own-data">Empezar con mis datos →</button>');return;}
  if(b.id==='confirm-own-data'){const d=dataset();d.demoArchive={rows:d.rows.filter(r=>r.source==='Datos de ejemplo'),goal:{...d.goal}};d.rows=d.rows.filter(r=>r.source!=='Datos de ejemplo');d.goal.saved=0;await persist();$('#detail-dialog').close();render();toast('Tu espacio está listo. Añade tu primer ingreso o gasto.');return;}
  if(b.dataset.action==='restore-demo'){modal('<h2>¿Restaurar los ejemplos?</h2><p>Se volverán a añadir los movimientos de ejemplo archivados. Tus registros propios y el progreso actual del objetivo se conservarán.</p><button class="button secondary" id="confirm-restore-demo">Restaurar ejemplos</button>');return;}
  if(b.id==='confirm-restore-demo'){const d=dataset();if(d.demoArchive){const ids=new Set(d.rows.map(r=>r.id));d.rows.push(...d.demoArchive.rows.filter(r=>!ids.has(r.id)));delete d.demoArchive;await persist();}$('#detail-dialog').close();render();toast('Ejemplos restaurados.');return;}
  if(b.dataset.view){route(state.profile,b.dataset.view);return;}
  if(b.dataset.chart){state.chart=b.dataset.chart;render();return;}
  if(b.dataset.filter){state.filter=b.dataset.filter;render();return;}
  if(b.hasAttribute('data-entity')){state.entity=Number(b.dataset.entity);state.month=dataset().lastMonth||state.month;await persist();render();return;}
  if(b.dataset.action==='clients'){clientTools();return;}
  if(b.dataset.evidence)return evidence(b.dataset.evidence);
  if(b.dataset.opportunity){const o=opportunityData().find(o=>o.id===b.dataset.opportunity);modal(`<span class="overline">${o.tag}</span><h2>${o.title}</h2><div class="evidence-value">${o.impact}</div><p>${o.desc}</p><dl class="evidence-details"><dt>Fórmula</dt><dd>${o.formula}</dd><dt>Fuente y periodo</dt><dd>${monthName(state.month)} · movimientos y objetivo del espacio actual. Incluye datos de ejemplo si no los has sustituido.</dd><dt>Supuestos y límites</dt><dd>${o.limits}</dd></dl><button class="button primary" data-go-goals>Explorar el escenario →</button>`);return;}
  if(b.hasAttribute('data-go-goals')){$('#detail-dialog').close();route(state.profile,'goals');return;}
  if(b.hasAttribute('data-lesson'))return openLesson(Number(b.dataset.lesson));
  if(b.hasAttribute('data-answer')){const index=Number(b.dataset.quiz),correct=Number(b.dataset.answer)===lessons[index].correct;b.classList.add(correct?'correct':'incorrect');$('#quiz-feedback').textContent=correct?`¡Un paso más! ${lessons[index].explain}`:'Prueba otra vez. Piensa en el objetivo del concepto.';if(correct){if(!dataset().lessons.includes(index)){dataset().lessons.push(index);await persist();}$$('[data-answer]').forEach(e=>e.disabled=true);$('#lesson-done').hidden=false;animate('#lesson-done');}return;}
  if(b.id==='lesson-done'){$('#detail-dialog').close();render();toast('Una pequeña victoria más. ¡Sigue a tu ritmo!');return;}
  if(b.dataset.delete){const row=dataset().rows.find(r=>r.id===b.dataset.delete);if(row){if(linkedRowIds(dataset()).has(row.id))throw new Error('Desvincula este pago de su deuda o partida antes de archivarlo.');dataset().trash=[...(dataset().trash||[]),row];dataset().rows=dataset().rows.filter(r=>r.id!==row.id);await persist();updateTable();toast('Movimiento archivado; el respaldo conserva su identificador.');}return;}
  if(b.dataset.action==='restore-row'){const d=dataset(),row=d.trash?.at(-1);if(row){d.rows=[...d.rows,row];d.trash=d.trash.slice(0,-1);await persist();render();toast('Movimiento restaurado con su identificador original.');}return;}
  if(b.dataset.action==='add')return addTransaction();
  if(b.dataset.action==='goal')return editGoal();
  if(b.dataset.action==='data-tools'){dataTools();return;}
  if(b.dataset.action==='import'){showCSVTools({getDestination:()=>({...dataset(),key:state.profile==='advisor'?`advisor-${state.entity}`:state.profile,name:dataset().name||config[state.profile].name}),modal,toast,apply:async(review,key)=>{const old=dataset(),next=applyImport(review,old,()=>crypto.randomUUID());state.datasets[key]=next;if(review.latestMonth)state.month=review.latestMonth;await persist();render();return next.rows.length-old.rows.length;}});return;}
  if(b.dataset.action==='export'){download(`finflow-${state.profile}-${state.month}.csv`,csvExport(currentRows()),'text/csv;charset=utf-8');toast('CSV del periodo exportado.');return;}
}catch(error){saveError(error);}});

document.addEventListener('submit',event=>{if(saving){event.preventDefault();event.stopImmediatePropagation();toast('Espera a que termine el guardado actual.');}},true);
document.addEventListener('submit',async event=>{try{
  if(event.target.id==='transaction-form'){
    event.preventDefault();const f=new FormData(event.target);
    try{
      const id=f.get('transactionId');const row=validateTransaction({date:f.get('date'),description:f.get('description'),category:f.get('category'),type:f.get('type'),amount:Number(f.get('amount')),financialType:f.get('financialType'),behavior:f.get('behavior'),source:id?'Editado':'Manual'});
      row.id=id||crypto.randomUUID();
      if(id)dataset().rows=dataset().rows.map(r=>r.id===id?row:r);else dataset().rows.push(row);
      state.month=row.date.slice(0,7);await persist();$('#detail-dialog').close();render();toast(id?'Movimiento actualizado. El resumen ya se recalculó.':'Movimiento guardado. Ya está en tus números.');
    }catch(e){$('#form-error').textContent=e.message;}
  }
  if(event.target.id==='currency-form'){event.preventDefault();const code=new FormData(event.target).get('currency');if(!isCurrencyCode(code))return;const key=state.profile==='advisor'?`advisor-${state.entity}`:state.profile;state.datasets[key]=changeCurrency(dataset(),code);await persist();$('#detail-dialog').close();render();toast('Moneda actualizada a '+code+'. Los importes se conservan.');return;}
  if(event.target.id==='settings-form'){
    event.preventDefault();const f=new FormData(event.target),month=f.get('month'),available=Number(f.get('available')),target=Number(f.get('savingsTarget')),budget=Number(f.get('expenseBudget')),unit=Number(f.get('unitPrice')||0);
    if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)||![available,target,budget,unit].every(Number.isFinite)||target<0||target>100||budget<0||unit<0){$('#form-error').textContent='Revisa el mes y los importes.';return;}
    const d=dataset();state.month=month;d.name=f.get('name').trim();if(!isCurrencyCode(f.get('currency'))){$('#form-error').textContent='Selecciona una moneda válida.';return;}d.currency=f.get('currency');const net=cashPosition(currentRows()).net;
    d.finance[month]={...d.finance[month],opening:currencyMath(d.currency).round(available-net),savingsTarget:target,expenseBudget:budget,unitPrice:unit};await persist();$('#detail-dialog').close();render();toast('Saldo, meta y presupuesto actualizados.');
  }
  if(event.target.id==='budget-form'){event.preventDefault();const f=new FormData(event.target),limit=Number(f.get('limit'));if(!Number.isFinite(limit)||limit<0)return;const key=state.profile==='advisor'?`advisor-${state.entity}`:state.profile;state.datasets[key]=saveBudget(dataset(),f.get('period'),f.get('category'),limit);await persist();$('#detail-dialog').close();render();toast('Presupuesto guardado.');}
  if(event.target.id==='goal-form'){event.preventDefault();const f=new FormData(event.target),target=Number(f.get('target')),saved=Number(f.get('saved'));if(!Number.isFinite(target)||target<=0||!Number.isFinite(saved)||saved<0){$('#form-error').textContent='Revisa los importes del objetivo.';return;}dataset().goal={name:f.get('name').trim(),target,saved};await persist();$('#detail-dialog').close();render();toast('Tu objetivo tiene un nuevo paso.');}
}catch(error){saveError(error);}});

document.addEventListener('input',event=>{if(event.target.id==='currency-search'){const selected=$('#currency-choice').value;const found=searchCurrencies(event.target.value);$('#currency-choice').innerHTML=currencyOptionsHTML(selected,found);$('#currency-save').disabled=!found.length;$('#currency-count').textContent=found.length+' '+(found.length===1?'moneda':'monedas');}if(event.target.id==='search')updateTable();if(['monthly','years','rate','fee','inflation'].includes(event.target.id)){state.scenario[event.target.id]=Number(event.target.value);updateScenario();}if(event.target.dataset.businessModel){const key=event.target.dataset.businessModel,value=Number(event.target.value),min=key==='salesChange'?-100:0,max=key==='salesChange'?500:100;if(Number.isFinite(value)&&value>=min&&value<=max){businessModel[key]=value;$('#business-scenario-result').innerHTML=renderBusinessScenario(currentRows(),businessModel,money,dataset().currency);}}});
document.addEventListener('change',async event=>{if(event.target.closest('#planning-panel'))return;if(saving){event.preventDefault();toast('Espera a que termine el guardado actual.');return;}try{if(event.target.id==='preview-currency'&&isCurrencyCode(event.target.value)){state.previewCurrency=event.target.value;await persist();refreshPreviewCurrency();}if(event.target.matches('#settings-form select[name=currency]')){const code=event.target.value;for(const name of ['available','expenseBudget','unitPrice']){const input=$('#settings-form input[name='+name+']');if(input)input.step=currencyStep(code);}const input=$('#settings-form input[name=available]');if(input)input.closest('label').firstChild.textContent='Disponible actual ('+code+')';}if(event.target.id==='type-filter')updateTable();if(event.target.id==='month-select'){state.month=event.target.value;render();await persist();}if(event.target.id==='transaction-type')$('#financial-type').innerHTML=financialOptions(event.target.value,event.target.value==='ingreso'?'revenue':'opex');}catch(error){saveError(error);}});

async function toggleTheme(){if(saving)return;state.theme=state.theme==='dark'?'light':'dark';document.documentElement.classList.toggle('dark',state.theme==='dark');try{await persist();}catch(error){saveError(error);}}
$('#theme-toggle').onclick=toggleTheme;$('#mobile-theme').onclick=toggleTheme;document.documentElement.classList.toggle('dark',state.theme==='dark');
$('#profile-switch').onclick=showProfiles;$('#breadcrumb').onclick=showProfiles;
$('#demo-button').onclick=()=>route('personal');$('#landing-button').onclick=()=>location.hash='';$('#home-link').onclick=()=>location.hash='';
$('#help-button').onclick=()=>modal('<span class="overline">TU ESPACIO, A LA VISTA</span><h2>Tus números, con más control.</h2><p>Desde Resumen puedes añadir ingresos y gastos o ajustar el disponible. La tasa se calcula desde los movimientos, y puedes fijar tu meta de ahorro en Configurar mes. En Movimientos puedes editar los registros.</p><p>Resultados añade el estado de gestión y el punto de equilibrio para empresas y profesionales. Fugas revisa patrones y presupuestos con datos verificables.</p><p>Tus cambios se guardan en este navegador y dominio. No se sincronizan con otros dispositivos ni se trasladan automáticamente entre el dominio Sites y sysora.io. Usa Mis datos y respaldos para llevar el espacio completo, o CSV para trasladar solo movimientos.</p><p>No hay conexión bancaria ni cotizaciones en vivo. Usa el nombre del espacio en la barra superior para cambiar de perfil.</p><button class="button secondary" id="modal-home">Volver a la web →</button>');
document.addEventListener('click',e=>{if(e.target.closest('#modal-home')){$('#detail-dialog').close();location.hash='';}});
if(new URLSearchParams(location.search).get('app')==='1'&&!location.hash)history.replaceState(null,'',`${location.pathname}?app=1#app/${state.profile}/overview`);
window.addEventListener('hashchange',renderRoute);hydrateIcons();refreshPreviewCurrency();renderRoute();
if(window.gsap){gsap.matchMedia().add('(prefers-reduced-motion: no-preference)',()=>{gsap.from('.hero-text > *',{autoAlpha:0,y:22,duration:.8,stagger:.075,ease:'power3.out'});gsap.from('.preview-window',{autoAlpha:0,y:35,rotation:3,duration:1,ease:'power3.out',delay:.15});gsap.from('.float-badge',{autoAlpha:0,scale:.85,y:18,duration:.8,stagger:.12,delay:.55,ease:'back.out(1.3)'});const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){gsap.fromTo(e.target,{autoAlpha:0,y:25},{autoAlpha:1,y:0,duration:.65,ease:'power3.out'});observer.unobserve(e.target);}}),{threshold:.15});$$('.profile-section,.how-section,.open-section').forEach(e=>observer.observe(e));return()=>observer.disconnect();});}

}
startWorkspace().catch(error=>{
 document.querySelector('#landing').hidden=true;document.querySelector('#workspace').hidden=true;
 const panel=document.createElement('main');panel.className='wrap';panel.style.padding='64px 24px';
 const title=document.createElement('h1');title.textContent='Protejamos tus datos.';
 const note=document.createElement('p');note.textContent=error.message||'No pudimos abrir el almacenamiento. Los datos anteriores se conservan.';
 const retry=document.createElement('button');retry.className='button primary';retry.textContent='Reintentar';retry.onclick=()=>location.reload();
 const backup=document.createElement('button');backup.className='button secondary';backup.textContent='Descargar copia anterior a la migración';backup.onclick=()=>{
  try{const raw=localStorage.getItem(workspaceStorageKey());if(!raw)throw new Error('No hay una copia anterior disponible.');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([raw],{type:'application/json'}));link.download='finflow-datos-anteriores.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}catch(e){note.textContent=e.message;}
 };
 panel.append(title,note,retry,backup);document.body.append(panel);
});
